class Solution {
public:
 vector<string> validateCoupons(vector<string>& code,vector<string>& businessLine,vector<bool>& isActive){
  map<string,int>ord={{"electronics",0},{"grocery",1},{"pharmacy",2},{"restaurant",3}};
  vector<pair<pair<int,string>,string>>a;
  for(int i=0;i<(int)code.size();++i){if(!isActive[i]||!ord.count(businessLine[i])||code[i].empty())continue;
   bool ok=true;for(char c:code[i])if(!isalnum((unsigned char)c)&&c!='_')ok=false;
   if(ok)a.push_back({{ord[businessLine[i]],code[i]},code[i]});}
  sort(a.begin(),a.end());vector<string>ans;for(auto &p:a)ans.push_back(p.second);return ans;
 }
};
